// Generates ../data.js — a deterministic, fully inline dataset.
// Run once: node tools/gen-data.mjs   (output is committed; do not edit data.js by hand)
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const SEED = 20261024;

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(SEED);
const gauss = () => {
  // Box–Muller
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
};
const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));

const PREFIX = ["North", "South", "East", "West", "Port", "New", "Alto", "Villa", "Grey", "Rose",
  "Storm", "Gold", "Iron", "Fair", "Bright", "Clear", "Deep", "Lake", "Mist", "Oak",
  "Star", "Wind", "Amber", "Corla"];
const CORE = ["Haven", "Meridian", "Barrow", "Cinder", "Dell", "Fenwick", "Hollow", "Kestrel", "Landing", "Marlow"];

const REGIONS = ["北湾", "南岸", "西岭", "东原", "高地", "群岛", "谷地", "湖岸"];
const REGION_OFFSET = {
  "北湾": { g: 10, gr: 0, a: 4 },
  "南岸": { g: 2, gr: 0, a: 5 },
  "西岭": { g: 6, gr: -1, a: -2 },
  "东原": { g: -2, gr: 1, a: -3 },
  "高地": { g: -6, gr: 8, a: 1 },
  "群岛": { g: 4, gr: 5, a: 4 },
  "谷地": { g: -4, gr: 2, a: -2 },
  "湖岸": { g: 0, gr: 4, a: 3 },
};
const TIERS = ["核心", "区域", "新兴"];

const N = 240;
const records = [];
for (let i = 0; i < N; i++) {
  const name = `${PREFIX[i % 24]} ${CORE[Math.floor(i / 24)]}`;
  const region = REGIONS[Math.floor(rng() * 8)];
  const off = REGION_OFFSET[region];

  const pop = Math.round(clamp(Math.exp(4.3 + 0.95 * gauss()), 18, 1450)); // 万人
  const gdp = Math.round(clamp(off.g + 16 * Math.exp(0.42 * gauss()) + (pop > 420 ? 8 : 0), 5, 128) * 10) / 10; // 千美元
  const transit = Math.round(clamp(20 + 0.5 * gdp + 6 * gauss(), 4, 98));
  const health = Math.round(clamp(24 + 0.6 * gdp + 5 * gauss(), 4, 99));
  const green = Math.round(clamp(4 + off.gr + 9 * gauss() + (pop < 90 ? 7 : 0), 1, 44));
  const air = Math.round(clamp(90 - 2.0 * Math.sqrt(pop) - 0.28 * gdp + 0.5 * green + off.a + 5 * gauss(), 3, 98));
  const housing = Math.round(clamp(96 - 0.9 * gdp - 0.055 * pop + 8 * gauss(), 4, 99));

  records.push({ id: i, name, region, tier: "", pop, gdp, transit, air, green, housing, health });
}
// tier by population percentile
const byPop = [...records].sort((a, b) => b.pop - a.pop);
byPop.forEach((r, rank) => { r.tier = rank < N * 0.15 ? TIERS[0] : rank < N * 0.5 ? TIERS[1] : TIERS[2]; });

const numDims = [
  { key: "pop", label: "人口", unit: "万", type: "numeric" },
  { key: "gdp", label: "人均 GDP", unit: "千美元", type: "numeric" },
  { key: "transit", label: "公共交通", unit: "分", type: "numeric" },
  { key: "air", label: "空气质量", unit: "分", type: "numeric" },
  { key: "green", label: "绿地率", unit: "%", type: "numeric" },
  { key: "housing", label: "住房可负担", unit: "分", type: "numeric" },
  { key: "health", label: "医疗资源", unit: "分", type: "numeric" },
].map((d) => {
  const vals = records.map((r) => r[d.key]);
  return { ...d, min: Math.min(...vals), max: Math.max(...vals) };
});
const catDims = [
  { key: "region", label: "区域", type: "category", values: REGIONS },
  { key: "tier", label: "层级", type: "category", values: TIERS },
];

const out = `// Atlas-240 · 城市宜居指标 — 内联数据集（合成立数据，seed ${SEED}）
// Generated by tools/gen-data.mjs — 提交为字面量数据，保证首屏零请求即就绪。勿手工编辑。
window.DATASET = ${JSON.stringify({ name: "Atlas-240 · 城市宜居指标", generatedBy: "tools/gen-data.mjs", seed: SEED, dimensions: [...numDims, ...catDims], records }, null, 1)};
`;
writeFileSync(join(here, "..", "data.js"), out, "utf8");
console.log(`data.js written: ${N} records, ${numDims.length + catDims.length} dimensions`);
